def transform(grid):
    from collections import Counter

    # Find background color (most frequent)
    counts = Counter()
    for row in grid:
        counts.update(row)
    background = max(counts, key=counts.get) if counts else 0

    h, w = len(grid), len(grid[0])
    # Legend row is second-to-last row
    legend_row = grid[-2] if h >= 2 else grid[0]

    visited = set()
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Work on a copy of the grid
    output = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != background and (r, c) not in visited:
                # Find connected component using BFS
                stack = [(r, c)]
                visited.add((r, c))
                component = [(r, c)]

                while stack:
                    cr, cc = stack.pop()
                    for dr, dc in dirs:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if grid[nr][nc] != background and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                stack.append((nr, nc))
                                component.append((nr, nc))

                # Find column span of this component
                cols = sorted(set(cc for _, cc in component))
                min_c, max_c = cols[0], cols[-1]

                # Find target color from legend row by scanning from right to left
                target_color = background  # default, means "preserve original"
                for cc in range(max_c, min_c - 1, -1):
                    if cc < len(legend_row):
                        lc = legend_row[cc]
                        if lc != background:
                            target_color = lc
                            break

                # Apply the target color to all pixels in the component
                for cr, cc in component:
                    if target_color != background:
                        output[cr][cc] = target_color

    return output
